//! Exact token lists over genuine inert Elements across namespaces.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://foreign-tokens.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn inert_foreign_class_list_xml_exact_reads_mutations_attrs_and_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createDocument('urn:original','p:Root'),source=owner.documentElement;source.setAttribute('Class','upper');source.setAttributeNS('urn:attribute','q:class','qualified');source.className=' A\ud800z A�z A\ud800z ';var a=source.getAttributeNode('class'),list=source.classList,descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'classList');if(list!==source.classList||list!==descriptor.get.call(source)||!(list instanceof DOMTokenList)||list.length!==2||list[0]!=='A\ud800z'||list.item(1)!=='A�z'||list.item(2)!==null||list[2]!==undefined||!list.contains('A\ud800z')||String(list)!==source.className)throw 'XML exact native reads';var watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});list.add('B\udfffz');list.remove('A�z');if(!list.replace('A\ud800z','C\ud800z')||list.replace('absent','new')||list.value!=='C\ud800z B\udfffz')throw 'XML mutations';if(!list.toggle('B\udfffz',true)||list.toggle('B\udfffz',false)||list.value!=='C\ud800z')throw 'XML toggle';source.classList='D\udfffz';a.value='E\ud800z';var records=watch.takeRecords();if(records.length!==6||records[0].oldValue!==' A\ud800z A�z A\ud800z '||records[5].oldValue!=='D\udfffz'||records[5].target!==source||list[0]!=='E\ud800z'||source.getAttributeNode('class')!==a||source.getAttribute('Class')!=='upper'||source.getAttributeNS('urn:attribute','class')!=='qualified')throw 'actual exact null namespace attribute';var count=0;list.forEach(function(v,i,l){if(v!==l.item(i)||l!==list)throw 'actual iterator';count++;});if(count!==1||Array.from(list).join('|')!=='E\ud800z')throw 'live iteration';
"#);}
#[test]
fn inert_foreign_class_list_no_slot_namespace_owners_remain_independent(){let(mut d,mut f,mut p)=fixture();let limit=p.state.node_limit;let count=d.nodes.len();p.state.node_limit=count;run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),nodes=[owner.createElementNS(null,'Root'),owner.createElementNS('urn:other','p:Root'),owner.createElementNS('http://www.w3.org/1998/Math/MathML','math'),owner.createElementNS('http://www.w3.org/2000/svg','svg')],lists=[];for(var i=0;i<nodes.length;i++){var n=nodes[i],list=n.classList;lists.push(list);list.add('A\ud800z','item'+i);if(list!==n.classList||list.value!=='A\ud800z item'+i||n.ownerDocument!==owner||n.getAttribute('class')!==list.value)throw 'no-slot native tokens';for(var j=0;j<i;j++)if(list===lists[j])throw 'independent owners';}lists[0].replace('A\ud800z','B\udfffz');if(lists[0].value!=='B\udfffz item0'||lists[1].value!=='A\ud800z item1'||lists[2].value!=='A\ud800z item2'||lists[3].value!=='A\ud800z item3')throw 'no-slot distinct state';
"#);assert_eq!(d.nodes.len(),count);p.state.node_limit=limit;}
#[test]
fn inert_foreign_class_list_clone_import_and_adoption_keep_actual_owner_and_saved_handle(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createDocument('urn:original','p:Root'),source=owner.documentElement,other=document.implementation.createDocument('urn:other','q:Root'),list=source.classList;list.value='A\ud800z';var a=source.getAttributeNode('class'),copy=source.cloneNode(true),imported=other.importNode(source,true);if(copy.classList===list||imported.classList===list||copy.classList===imported.classList||copy.classList.value!==list.value||imported.classList.value!==list.value||copy.ownerDocument!==owner||imported.ownerDocument!==other)throw 'independent token clone';var watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});if(other.adoptNode(source)!==source||source.ownerDocument!==other||source.classList!==list||source.getAttributeNode('class')!==a||a.ownerDocument!==other)throw 'actual adopted owner and handle';list.add({toString:function(){source.className='fresh';return 'B\udfffz';}});var records=watch.takeRecords();if(list.value!=='fresh B\udfffz'||copy.classList.value!=='A\ud800z'||imported.classList.value!=='A\ud800z'||records.length!==2||records[1].oldValue!=='fresh'||records[1].target!==source)throw 'current adopted attributes after conversion';
"#);}

#[test]
fn inert_foreign_class_list_only_mutates_null_namespace_class_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createDocument(null,'Root'),source=owner.documentElement;source.setAttributeNS('urn:attribute','class','namespaced');source.setAttribute('Class','upper');var foreign=source.getAttributeNodeNS('urn:attribute','class'),list=source.classList;if(list.value!==''||list.length||source.className!=='')throw 'null namespace reads';list.add('A\ud800z');var a=source.getAttributeNodeNS(null,'class');if(a===foreign||a.value!==list.value||foreign.value!=='namespaced'||source.getAttribute('Class')!=='upper')throw 'null namespace token write';list.value='B\udfffz';source.className='C\ud800z';if(a.value!=='C\ud800z'||list.value!==a.value||foreign.value!=='namespaced'||source.getAttributeNodeNS('urn:attribute','class')!==foreign||source.attributes.length!==3)throw 'shared native value setter';"#);}
#[test]
fn inert_foreign_class_list_saved_child_origin_precedes_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createDocument(null,'Root'),source=owner.documentElement,list=source.classList;list.value='seed';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var add=frame.contentWindow.DOMTokenList.prototype.add,calls=0;add.call(list,'A\ud800z');"#);let before=(d.nodes.len(),p.state.attributes.len(),p.state.dom_commits);p.set_location(&crate::navigation::address("https://other-foreign-tokens.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("add.call(list,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!((d.nodes.len(),p.state.attributes.len(),p.state.dom_commits),before);p.set_location(&crate::navigation::address("https://foreign-tokens.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||list.value!=='seed A\\ud800z')throw 'origin before conversion';add.call(list,'fresh');if(list.value!=='seed A\\ud800z fresh')throw 'fresh recovery';");}
#[test]
fn inert_foreign_class_list_conversion_validation_empty_updates_and_abrupt_effects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createDocument('urn:original','p:Root'),source=owner.documentElement,list=source.classList,watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});list.add();list.remove();if(source.hasAttribute('class')||watch.takeRecords().length)throw 'absent empty update';list.value='';list.add();if(!source.hasAttribute('class')||watch.takeRecords().length!==2)throw 'present empty update';source.className='seed';watch.takeRecords();var order='',marker={};try{list.add({toString:function(){order+='a';return 'good';}},{toString:function(){order+='b';return 'bad token';}});throw 'invalid token accepted';}catch(e){if(e.name!=='InvalidCharacterError')throw e;}if(order!=='ab'||list.value!=='seed'||watch.takeRecords().length)throw 'all conversions before atomic validation';try{list.add({toString:function(){source.setAttribute('data-effect','effect');throw marker;}});throw 'abrupt missing';}catch(e){if(e!==marker)throw e;}if(list.value!=='seed'||source.getAttribute('data-effect')!=='effect')throw 'abrupt effects';var calls=0,add=DOMTokenList.prototype.add;try{add.call({}, {toString:function(){calls++;return 'bad';}});throw 'bad brand';}catch(e){if(!(e instanceof TypeError))throw e;}try{list.add(Symbol());throw 'Symbol accepted';}catch(e){if(!(e instanceof TypeError))throw e;}try{list.supports('anything');throw 'supports accepted';}catch(e){if(!(e instanceof TypeError))throw e;}if(calls||list.value!=='seed')throw 'brand and Symbol ordering';list.add('fresh');if(list.value!=='seed fresh')throw 'validation recovery';
"#);}
#[test]
fn inert_foreign_class_list_resource_and_cancellation_refusal_preserve_real_source_and_recover(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createDocument('urn:original','p:Root'),source=owner.documentElement;source.className='A\ud800z';var list=source.classList,a=source.getAttributeNode('class'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});"#);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;
for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.limits.host.string_bytes=4};let e=p.runtime.execute(r#"list.add('longB\udfffz');"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;}
p.begin_job();run(&mut d,&mut f,&mut p,&format!("if(list.value!=='A\\ud800z'||a.value!==list.value||watch.takeRecords().length)throw 'refusal publication';var longValue='{}';source.className=longValue;watch.takeRecords();","x".repeat(5000)));let state=(p.state.retained,p.state.dom_commits);p.begin_job();p.state.execution_deadline=Some(Instant::now());let e=p.runtime.execute("list.add('fresh');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("time limit"),"{e}");assert_eq!((p.state.retained,p.state.dom_commits),state);p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.className!==longValue||a.value!==source.className||watch.takeRecords().length)throw 'cancelled publication';list.value='recovered';if(a.value!=='recovered'||watch.takeRecords().length!==1)throw 'fresh recovery';");}
#[test]
fn inert_foreign_class_list_scoped_snapshot_and_output_share_headroom_and_handles_remain_typed(){let(mut d,mut f,mut p)=fixture();let nodes=p.state.node_limit;p.state.node_limit=d.nodes.len();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('urn:other','p:Root');source.className='A\ud800z B\udfffz';var list=source.classList;"#);let value=p.runtime.execute("list;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();let Value::Host(list)=value else{panic!()};let retained=p.state.retained;let limit=p.state.retained_limit;let commits=p.state.dom_commits;let snapshot=2*size_of::<crate::dom_string::DomStringRef<'_>>();let output=DomString::from_units(&[65,0xd800,122],64).unwrap().capacity();
for(headroom,needle)in[(snapshot-1,"snapshot"),(snapshot+output-1,"output")]{p.begin_job();p.state.retained_limit=retained+headroom;let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.class_list_get(list,"0").unwrap_err();assert!(error.contains(needle)&&error.contains("allowance"),"{error}");assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));}
p.begin_job();p.state.retained_limit=retained+snapshot+output;let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.class_list_get(list,"0").unwrap();assert!(matches!(value,Value::StringUnits(u)if u==[65,0xd800,122]));assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.node_limit=nodes;p.begin_job();
for handle in[0xc200_0000,0xc2ff_ffff,script_class_list::handle(script_inert_documents::ENTRY_END-1)]{let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(!bridge.class_list_receiver(handle));assert!(bridge.class_list_get(handle,"length").is_err());assert!(!bridge.named_map_receiver(handle));}
let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(bridge.class_list_receiver(list));assert!(!bridge.named_map_receiver(list));assert_eq!(bridge.class_list_keys(list).unwrap(),["0","1"]);assert_eq!(bridge.state.retained,retained);}

